fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Vec<Vec<i8>> {
    // Extract the dimensions R and C from the shape vector
    let r = shape[0] as usize; // Number of rows
    let c = shape[1] as usize; // Number of columns
    let a_len = a.len(); // Length of the input array

    // Create a new matrix with R rows and C columns
    let mut matrix = vec![vec![0; c]; r];

    // Fill the matrix based on the broadcasting rules
    if a_len == r {
        // Treat `a` as a column vector
        for i in 0..r {
            matrix[i] = a.clone(); // Each row gets the corresponding element from `a`
        }
    } else if a_len == c {
        // Treat `a` as a row vector
        for i in 0..r {
            for j in 0..c {
                matrix[i][j] = a[j]; // Each column gets the corresponding element from `a`
            }
        }
    }

    matrix
}